static inline float relu(float x) { return (x > 0.0f) ? x : 0.0f; }

static float ann_predict(float *input) {
    float norm_in[NN_INPUT_DIM];
    for (int i = 0; i < NN_INPUT_DIM; i++) {
        norm_in[i] = (input[i] - scaler_mean[i]) / scaler_scale[i];
    }

    float h1[128];
    for (int i = 0; i < 128; i++) {
        float sum = b0[i];
        for (int j = 0; j < NN_INPUT_DIM; j++) {
            sum += W0[i * NN_INPUT_DIM + j] * norm_in[j];
        }
        h1[i] = relu(sum);
    }

    float h2[128];
    for (int i = 0; i < 128; i++) {
        float sum = b1[i];
        for (int j = 0; j < 128; j++) {
            sum += W1[i * 128 + j] * h1[j];
        }
        h2[i] = relu(sum);
    }

    float out = b2[0];
    for (int i = 0; i < 128; i++) {
        out += W2[i] * h2[i];
    }

    // Saturacao estrita bidirecional [-80%, +80%]
    if (out > 80.0f) out = 80.0f;
    if (out < -80.0f) out = -80.0f;
    return out;
}
